// ====== KONFIGURASI ======
// Isi nomor WhatsApp penjual (format internasional tanpa +, mis. 6281234567890).
const WA_NUMBER = "6285891058813";
const LOKASI = "SMAN 17 Jakarta";
// =========================
const IMG={"churros": "data:image/jpeg;base64,", "pisang": "data:image/jpeg;base64,", "mochi": "data:image/jpeg;base64,", "cheese": "data:image/jpeg;base64,", "donat": "data:image/jpeg;base64,", "dimsum": "data:image/jpeg;base64,", "cimol": "data:image/jpeg;base64,", "corndog": "data:image/jpeg;base64,", "kebab": "data:image/jpeg;base64,", "fries": "data:image/jpeg;base64,"};
const P=[
{id:1,c:"savory",n:"Dimsum Mentai",p:15000,i:"dimsum",d:"Dimsum torched dengan saus mentai, nori & tobiko."},
{id:2,c:"savory",n:"Cimol Keju (Isi 8)",p:10000,i:"cimol",d:"Cimol goreng isi keju leleh, bumbu gurih. 8 pcs."},
{id:3,c:"savory",n:"Corndog",p:15000,i:"corndog",d:"Corndog crispy mozzarella & sosis, saus mustard & saus tomat."},
{id:4,c:"savory",n:"Kebab Sapi",p:15000,i:"kebab",d:"Kebab daging sapi cincang, selada & mayones. Ukuran kecil."},
{id:5,c:"savory",n:"Kentang Goreng",p:12000,i:"fries",d:"Kentang renyah dengan sea salt & saus cocolan."},
{id:6,c:"sweet",n:"Churros",p:10000,i:"churros",d:"Churros renyah dengan taburan gula kayu manis."},
{id:7,c:"sweet",n:"Pisang Keju Coklat",p:7000,i:"pisang",d:"Pisang goreng manis, topping coklat dan keju parut."},
{id:8,c:"sweet",n:"Mochi Daifuku",p:15000,i:"mochi",d:"Mochi kenyal dengan isian pasta manis."},
{id:9,c:"sweet",n:"Cheese Cuit",p:15000,i:"cheese",d:"Biskuit lapis krim keju lumer yang lembut."},
{id:10,c:"sweet",n:"Donat Gula",p:5000,i:"donat",d:"Donat ring klasik, freshly-baked."}];
const rp=n=>"Rp"+n.toLocaleString("id-ID");
let C={},cat="all",term="";
try{C=JSON.parse(localStorage.getItem("mavera_cart")||"{}")}catch(e){}
const $=id=>document.getElementById(id);
function toast(t){const e=$("toast");e.textContent=t;e.classList.add("on");clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove("on"),1800)}
function render(){
 const f=P.filter(x=>(cat=="all"||x.c==cat)&&x.n.toLowerCase().includes(term));
 const g=(k,t)=>{const a=f.filter(x=>x.c==k);return a.length?`<h3 class="grp serif">${t}</h3><div class="grid">${a.map((x,j)=>`<div class="card" style="animation-delay:${j*.06}s"><img src="${IMG[x.i]}" alt="${x.n}"><div class="in"><h3>${x.n}</h3><p>${x.d}</p><div class="row"><span class="pr">${rp(x.p)}</span><button class="add" onclick="add(${x.id})" aria-label="Tambah ${x.n}">+</button></div></div></div>`).join("")}</div>`:""};
 $("list").innerHTML=(g("savory","🧀 Savory Menu")+g("sweet","🍩 Sweet Menu"))||'<p class="none">Menu tidak ditemukan 🥲</p>'}
function save(){try{localStorage.setItem("mavera_cart",JSON.stringify(C))}catch(e){}drawCart()}
function add(id){C[id]=(C[id]||0)+1;save();toast("Ditambahkan ke keranjang 🧡")}
function chg(id,d){C[id]=(C[id]||0)+d;if(C[id]<=0)delete C[id];save()}
function del(id){delete C[id];save()}
const lines=()=>P.filter(x=>C[x.id]).map(x=>({...x,q:C[x.id],s:C[x.id]*x.p}));
function drawCart(){
 const L=lines(),t=L.reduce((a,x)=>a+x.s,0),n=L.reduce((a,x)=>a+x.q,0);
 $("cnt").textContent=n;$("tot").textContent=rp(t);$("ord").href=n?"https://wa.me/"+WA_NUMBER+"?text="+encodeURIComponent(msg(L,t)):"#";$("ord").style.opacity=n?1:.4;$("ord").style.pointerEvents=n?"auto":"none";
 $("sum").textContent=n?`${n} item · Ambil di ${LOKASI}`:"";
 $("items").innerHTML=L.length?L.map(x=>`<div class="it"><img src="${IMG[x.i]}" alt=""><div class="n"><b>${x.n}</b><br>${rp(x.p)} · <b>${rp(x.s)}</b></div><div class="q"><button onclick="chg(${x.id},-1)">−</button>${x.q}<button onclick="chg(${x.id},1)">+</button></div><button class="del" onclick="del(${x.id})" aria-label="Hapus">🗑️</button></div>`).join(""):'<p class="none">Keranjang masih kosong 🛍️<br>Yuk pilih camilan!</p>'}
function cart(o){$("dr").classList.toggle("on",!!o);$("ov").classList.toggle("on",!!o)}
function wa(msg){
 let num=WA_NUMBER;
 if(!num){try{num=localStorage.getItem("mavera_wa")||""}catch(e){}}
 if(!num){num=(prompt("Nomor WhatsApp penjual belum diatur.\nMasukkan nomor (contoh 6281234567890), atau isi WA_NUMBER di konfigurasi kode:")||"").replace(/\D/g,"");
  if(!num)return;if(num.startsWith("0"))num="62"+num.slice(1);try{localStorage.setItem("mavera_wa",num)}catch(e){}}
 const a=document.createElement("a");a.href="https://wa.me/"+num+"?text="+encodeURIComponent(msg);a.target="_blank";a.rel="noopener";document.body.appendChild(a);a.click();a.remove()}
function msg(L,t){return `Halo MAVÉRA! Saya ingin memesan:\n\n${L.map(x=>`- ${x.n} x${x.q} = ${rp(x.s)}`).join("\n")}\n\nTotal: ${rp(t)}\n\nLokasi pengambilan: ${LOKASI}.\n\nTerima kasih!`}
function checkout(){
 const L=lines();if(!L.length)return;
 const t=L.reduce((a,x)=>a+x.s,0);
 wa(`Halo MAVÉRA! Saya ingin memesan:\n\n${L.map(x=>`- ${x.n} x${x.q} = ${rp(x.s)}`).join("\n")}\n\nTotal: ${rp(t)}\n\nLokasi pengambilan: ${LOKASI}.\n\nTerima kasih!`)}
document.querySelectorAll(".tab").forEach(b=>b.onclick=()=>{document.querySelectorAll(".tab").forEach(x=>x.classList.remove("on"));b.classList.add("on");cat=b.dataset.c;render()});
$("q").oninput=e=>{term=e.target.value.toLowerCase().trim();render()};
render();drawCart();